@Service
public class OrderService {

    @Autowired
    private BillingService billingService;

    @Autowired
    private AuditLogService auditLogService;

    @Transactional(propagation = Propagation.REQUIRED)
    public void placeOrder(Order order) {
        // Core business logic runs in REQUIRED
        orderRepository.save(order);
        billingService.processPayment(order);

        try {
            // REQUIRES_NEW ensures audit log commits even if something else fails later
            auditLogService.logSuccessAsync(order);
        } catch (Exception e) {
            logger.warn("Audit log failed to persist independently", e);
        }
    }
}

@Service
public class AuditLogService {

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void logSuccessAsync(Order order) {
        auditRepository.save(new AuditRecord(order.getId(), "COMPLETED"));
    }
}
